from pathlib import Path
import json, hashlib, re
B=Path('/workspace/riemann-observatory')
D='2026-11-17'
records=[]
def rec(id,arxiv,title,authors,year,level,scope,venue=None,doi=None,version='v1'):
 h=(B/'sources/analytic'/f'{arxiv}.html').read_text()
 r=dict(paper_id=id,title=title,authors=authors,year=year,date=D,arxiv_id=arxiv,version=version,venue=venue,doi=doi,canonical_url=f'https://arxiv.org/abs/{arxiv}{version}',source_url=f'https://arxiv.org/pdf/{arxiv}{version}',publication_status='journal' if venue else 'preprint',full_text_access='pdf downloaded and text extracted',bibliographic_verified=True,full_text_accessed=True,substantive_reading=level>=1,audit_level=level,audit_scope=scope,source_sha256=hashlib.sha256((B/'sources/analytic'/f'{arxiv}.pdf').read_bytes()).hexdigest(),access_date=D,correction_search='Targeted web searches; no exhaustive correction certification. arXiv landing/version history inspected.')
 version_dates={'2405.20552':('2024-05-31','2026-04-07',2026),'2004.09765':('2020-04-21','2020-04-21',2021),'2609.02882':('2026-09-02','2026-09-08',None),'2608.13637':('2026-08-13','2026-08-19',None),'2610.08965':('2026-10-06','2026-10-06',None),'2306.04799':('2023-06-07','2023-06-07',2024)}
 first,vd,pub=version_dates[arxiv]
 r.update(date=vd,version_date=vd,first_submission_date=first,preprint_year=int(first[:4]),publication_year=pub,publication_date=str(pub) if pub else None,year=pub or int(first[:4]),date_semantics='date/version_date is inspected preprint version date; access_date is retrieval; journal date known at year precision only')
 records.append(r);return r
