rec('PAPER-A006','2306.04799','An unconditional Montgomery Theorem for Pair Correlation of Zeros of the Riemann Zeta Function',['Siegfred Alan C. Baluyot','Daniel Alan Goldston','Ade Irma Suriajaya','Caroline L. Turnage-Butterbaugh'],2023,0,'Partial technical reading: introduction Theorems1–3 and §3 Lemma5/proof. Entire analytic theorem proof not audited.','Acta Arithmetica 214 (2024), 357–376','10.4064/aa230612-20-3')
